/* Energies eV; time fs; positions nm. One ground + N localized excitations. */
export const HBAR=0.6582119569;
export const defaults={n:12,radius:1.2,rise:0.36,twist:55,j:0.025,drive:0.006,pol:'x',gamma:0.003,relax:0.0005,disorder:0,fluct:0,carrier:5,center:80,sigma:25,end:500,dt:0.5};
export function geometry(p){return Array.from({length:p.n},(_,i)=>{let a=i*p.twist*Math.PI/180;return {r:[p.radius*Math.cos(a),p.radius*Math.sin(a),(i-(p.n-1)/2)*p.rise],mu:[-Math.sin(a)*Math.sqrt(.75),Math.cos(a)*Math.sqrt(.75),.5]};});}
export function model(params={}){const p={...defaults,...params},g=geometry(p),d=p.n+1,H=new Float64Array(d*d);const dot=(a,b)=>a.reduce((s,x,i)=>s+x*b[i],0);let r0=Math.hypot(...g[0].r.map((x,k)=>x-g[1].r[k]));for(let i=0;i<p.n;i++){H[(i+1)*d+i+1]=p.disorder*Math.sin((i+1)*12.9898);for(let j=0;j<i;j++){let v=g[i].r.map((x,k)=>x-g[j].r[k]),r=Math.hypot(...v),u=v.map(x=>x/r);let c=p.j*Math.pow(r0/r,3)*(dot(g[i].mu,g[j].mu)-3*dot(g[i].mu,u)*dot(g[j].mu,u));H[(i+1)*d+j+1]=H[(j+1)*d+i+1]=c;}}return {p,g,d,H};}
export function envelope(t,p){return Math.exp(-.5*((t-p.center)/p.sigma)**2);}
export function hamiltonian(m,t){let H=m.H.slice(),{d,p,g}=m,k={x:0,y:1,z:2}[p.pol];for(let i=1;i<d;i++){H[i]=H[i*d]=-p.drive*envelope(t,p)*g[i-1].mu[k];H[i*d+i]+=p.fluct*Math.sin(2*Math.PI*t/(110+7*i)+i*1.618);}return H;}
export function derivative(m,t,y){const {d,p}=m,L=d*d,H=hamiltonian(m,t),out=new Float64Array(2*L);for(let a=0;a<d;a++)for(let b=0;b<d;b++){let re=0,im=0;for(let k=0;k<d;k++){re+=H[a*d+k]*y[k*d+b]-y[a*d+k]*H[k*d+b];im+=H[a*d+k]*y[L+k*d+b]-y[L+a*d+k]*H[k*d+b];}let idx=a*d+b;out[idx]=im/HBAR;out[L+idx]=-re/HBAR;let deph=a===b?0:p.gamma*((a>0)+(b>0))/2;let loss=p.relax*((a>0)+(b>0))/2;out[idx]-=(deph+loss)*y[idx];out[L+idx]-=(deph+loss)*y[L+idx];}for(let i=1;i<d;i++)out[0]+=p.relax*y[i*d+i];return out;}
export function step(m,t,y,dt){let add=(k,s)=>y.map((v,i)=>v+s*k[i]);let a=derivative(m,t,y),b=derivative(m,t+dt/2,add(a,dt/2)),c=derivative(m,t+dt/2,add(b,dt/2)),e=derivative(m,t+dt,add(c,dt));return y.map((v,i)=>v+dt*(a[i]+2*b[i]+2*c[i]+e[i])/6);}
export function observables(m,y,t){let {d,g,p}=m,L=d*d,pop=[],dip=[0,0,0],phase=[],amp=[],purity=0,coherence=0;for(let q=0;q<L;q++)purity+=y[q]**2+y[L+q]**2;for(let i=1;i<d;i++){pop.push(y[i*d+i]);phase.push(Math.atan2(y[L+i*d],y[i*d]));amp.push(Math.hypot(y[i*d],y[L+i*d]));for(let k=0;k<3;k++)dip[k]+=2*g[i-1].mu[k]*y[i*d];for(let j=1;j<d;j++)if(i!==j)coherence+=Math.hypot(y[i*d+j],y[L+i*d+j]);}let excited=pop.reduce((s,x)=>s+x,0),pr=excited>1e-9?excited**2/pop.reduce((s,x)=>s+x*x,0):0;let ar=0,ai=0,weight=0;for(let i=0;i<amp.length;i++){ar+=amp[i]*Math.cos(phase[i]);ai+=amp[i]*Math.sin(phase[i]);weight+=amp[i];}return {t,pop,phase,amp,excited,pr,coherence,purity,dip,order:weight>1e-8?Math.hypot(ar,ai)/weight:0,pulse:envelope(t,p)};}
export function simulate(params={}){let m=model(params),{p,d}=m,y=new Float64Array(2*d*d);y[0]=1;let frames=[],stride=Math.max(1,Math.round(2/p.dt)),steps=Math.round(p.end/p.dt);for(let s=0;s<=steps;s++){let t=s*p.dt;if(s%stride===0||s===steps)frames.push({...observables(m,y,t),rho:Array.from(y)});if(s<steps)y=step(m,t,y,p.dt);}return {m,frames,spectrum:spectrum(m)};}
export function spectrum(m){let n=m.p.n,A=Array.from({length:n},(_,i)=>Array.from({length:n},(_,j)=>m.H[(i+1)*m.d+j+1])),V=Array.from({length:n},(_,i)=>Array.from({length:n},(_,j)=>+(i===j)));for(let iter=0;iter<n*n*50;iter++){let a=0,b=1,max=0;for(let i=0;i<n;i++)for(let j=i+1;j<n;j++)if(Math.abs(A[i][j])>max){max=Math.abs(A[i][j]);a=i;b=j;}if(max<1e-12)break;let theta=.5*Math.atan2(2*A[a][b],A[b][b]-A[a][a]),c=Math.cos(theta),s=Math.sin(theta),aa=A[a][a],bb=A[b][b],ab=A[a][b];for(let k=0;k<n;k++)if(k!==a&&k!==b){let ka=A[k][a],kb=A[k][b];A[k][a]=A[a][k]=c*ka-s*kb;A[k][b]=A[b][k]=s*ka+c*kb;}A[a][a]=c*c*aa-2*s*c*ab+s*s*bb;A[b][b]=s*s*aa+2*s*c*ab+c*c*bb;A[a][b]=A[b][a]=0;for(let k=0;k<n;k++){let va=V[k][a],vb=V[k][b];V[k][a]=c*va-s*vb;V[k][b]=s*va+c*vb;}}let k={x:0,y:1,z:2}[m.p.pol],lines=Array.from({length:n},(_,j)=>({energy:m.p.carrier+A[j][j],strength:m.g.reduce((s,g,i)=>s+g.mu[k]*V[i][j],0)**2}));return {lines,points:Array.from({length:241},(_,i)=>{let x=4.8+i*.4/240;return {x,y:lines.reduce((s,l)=>s+l.strength*.012**2/((x-l.energy)**2+.012**2),0)};})};}
